BEGIN TRANSACTION;

-- 1. THÔNG TIN DỰ ÁN
CREATE TABLE IF NOT EXISTS revit_model_info (
    project_name NVARCHAR(255),
    file_path NVARCHAR(500),
    export_time NVARCHAR(50),
    revit_version VARCHAR(20),
    total_elements INT
);

DELETE FROM revit_model_info WHERE project_name = 'Project Name';
VALUES ('Project Name', 'C:\Users\thanhvp\Documents\BSV-SCS3.2B-TC-SH2-M3-KC-V1_autodesk21BATJ4.rvt', '2026-09-17 15:50:56', '2024/2026', 1056);

-- 2. BẢNG TỔNG HỢP KHỐI LƯỢNG THEO ĐỀ MỤC CẤU KIỆN (BoQ SUMMARY)
CREATE TABLE IF NOT EXISTS revit_boq_summary (
    category_code VARCHAR(50) PRIMARY KEY,
    category_name NVARCHAR(100),
    element_count INT,
    total_volume_m3 REAL,
    total_area_m2 REAL,
    total_rebar_weight_kg REAL
);

DELETE FROM revit_boq_summary;

-- 3. BẢNG CHI TIẾT TỪNG CẤU KIỆN (ELEMENT DETAILS)
CREATE TABLE IF NOT EXISTS revit_boq_elements (
    element_id INT PRIMARY KEY,
    unique_id VARCHAR(64),
    category_code VARCHAR(50),
    category_name NVARCHAR(100),
    family_name NVARCHAR(255),
    type_name NVARCHAR(255),
    level_name NVARCHAR(100),
    volume_m3 REAL,
    area_m2 REAL,
    length_m REAL,
    material_name NVARCHAR(100),
    comments NVARCHAR(500),
    mark NVARCHAR(100),
    bsv_phanloai NVARCHAR(255),
    bsv_comments NVARCHAR(255),
    partition NVARCHAR(100),
    rebar_diameter_mm REAL,
    rebar_length_m REAL,
    rebar_weight_kg REAL
);

DELETE FROM revit_boq_elements;

COMMIT;
